import { DevtoolsProvider } from '@axonpack/expo-devtools';

export default function App() {
  return (
    <DevtoolsProvider
      config={{
        // The whole production gate. Off means nothing is patched at all.
        enabled: __DEV__,
        defaultTheme: 'dark',
        network: { http: true, websocket: true, sse: true },
        console: { capture: true, repl: true },
      }}>
      <YourApp />
    </DevtoolsProvider>
  );
}
